`, "",{"version":3,"sources":["webpack://./src/wxhl-cg/ui/ExchangePanel.vue"],"names":[],"mappings":"AA0OA,2BACE,cAAe,CACf,OAAQ,CACR,kBAAmB,CACnB,aAAc,CACd,mBAAoB,CACpB,YAAa,CACb,qBAAsB,CACtB,cACF,CACA,0BACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,iBAAkB,CAClB,+BACF,CACA,2BACE,eACF,CACA,yBACE,gBAAiB,CACjB,WACF,CACA,2BACE,eAAgB,CAChB,WAAY,CACZ,UAAW,CACX,cACF,CACA,0BACE,gBAAiB,CACjB,kBAAmB,CACnB,cACF,CACA,0BACE,YAAa,CACb,OAAQ,CACR,gBACF,CACA,iCACE,MAAO,CACP,WAAY,CACZ,kBAAmB,CACnB,wBAAyB,CACzB,UAAW,CACX,iBACF,CACA,oCACE,kBAAmB,CACnB,UACF,CACA,0BACE,MAAO,CACP,eAAgB,CAChB,cACF,CACA,yBACE,YAAa,CACb,kBAAmB,CACnB,QAAS,CACT,cAAe,CACf,+BACF,CACA,8BACE,MACF,CACA,0BACE,WAAY,CACZ,eAAgB,CAChB,cACF,CACA,4BACE,aACF,CACA,8BACE,aACF,CACA,wDAEE,YAAa,CACb,YAAa,CACb,qBAAsB,CACtB,QACF,CACA,0BACE,YAAa,CACb,QACF,CACA,+BACE,MAAO,CACP,kBAAmB,CACnB,UAAW,CACX,WAAY,CACZ,YAAa,CACb,iBACF,CACA,gCACE,MAAO,CACP,kBAAmB,CACnB,UAAW,CACX,WAAY,CACZ,YAAa,CACb,iBACF,CACA,2BACE,WAAY,CACZ,iBAAkB,CAClB,YACF,CACA,4BACE,aACF,CACA,yBACE,kBAAmB,CACnB,aAAc,CACd,wBAAyB,CACzB,WAAY,CACZ,iBACF,CACA,2BACE,wBAAyB,CACzB,kBAAmB,CACnB,iBAAkB,CAClB,YAAa,CACb,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,cACF","sourcesContent":["<!-- 回廊交易所 · 主面板：行情 / 持仓 / 资产 -->\n<script setup lang=\"ts\">\nimport { useExchangeStore } from '../store';\nimport { STOCKS } from '../engine/stocks';\nimport { netAssets, openPosition, closePosition, positionPnl, liquidationPrice } from '../engine/trading';\nimport type { LiquidationResult } from '../engine/bankruptcy';\nimport SparkLine from './SparkLine.vue';\n\nconst store = useExchangeStore();\nconst acct = computed(() => store.acct);\nconst tab = ref<'market' | 'positions' | 'loan' | 'assets'>('market');\nconst detail = ref<string | null>(null);\nconst qty = ref(1);\nconst leverage = ref(1);\n\nconst net = computed(() => netAssets(acct.value));\n\nfunction pct(code: string): number {\n  const h = acct.value.priceHistory[code];\n  if (!h || h.length < 2) return 0;\n  return ((h[h.length - 1] - h[0]) / h[0]) * 100;\n}\n\nfunction buy(code: string, side: 'long' | 'short') {\n  try {\n    openPosition(acct.value, code, side, qty.value, leverage.value);\n    store.persist();\n    toastr.success(`已开${side === 'long' ? '多' : '空'} ${code} ×${qty.value}`);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '开仓失败');\n  }\n}\n\nfunction close(code: string) {\n  try {\n    const r = closePosition(acct.value, code);\n    store.persist();\n    toastr.success(`平仓 ${code}：盈亏 ${r.pnl >= 0 ? '+' : ''}${r.pnl}`);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '平仓失败');\n  }\n}\n\nconst exchangeAmt = ref(0);\nasync function doDeposit() {\n  try {\n    await store.depositUP(exchangeAmt.value);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '入金失败');\n  }\n}\nasync function doWithdraw() {\n  try {\n    await store.withdrawUP(exchangeAmt.value);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '出金失败');\n  }\n}\n\nconst loanAmt = ref(0);\nconst debtAmt = ref(0);\nconst previewing = ref(false);\nconst preview = ref<LiquidationResult | null>(null);\n\nfunction openPreview() {\n  try {\n    preview.value = store.previewBankruptcy();\n    previewing.value = true;\n  } catch (e: any) {\n    toastr.error(e?.message ?? '清算预览失败');\n  }\n}\nfunction doBorrow() {\n  try {\n    store.borrow(loanAmt.value);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '借款失败');\n  }\n}\nfunction doRepay() {\n  try {\n    store.repay();\n  } catch (e: any) {\n    toastr.error(e?.message ?? '还款失败');\n  }\n}\nfunction doBorrowHigh() {\n  try {\n    store.borrowHigh();\n  } catch (e: any) {\n    toastr.error(e?.message ?? '高利贷失败');\n  }\n}\nfunction doPayDebt() {\n  try {\n    store.payDebt(debtAmt.value);\n  } catch (e: any) {\n    toastr.error(e?.message ?? '还债失败');\n  }\n}\nasync function doBankruptcy() {\n  try {\n    await store.declareBankruptcy();\n    previewing.value = false;\n    toastr.warning('破产清算完成——愿你下局好运');\n  } catch (e: any) {\n    toastr.error(e?.message ?? '清算失败，已中止');\n  }\n}\n\nconst confirmDeath = ref(false);\nfunction doMarkDeath() {\n  store.markDeath();\n  confirmDeath.value = false;\n}\n</script>\n\n<template>\n  <div v-if=\"store.panelOpen\" class=\"cg-panel\">\n    <div class=\"cg-head\">\n      <span class=\"cg-title\">回廊交易所</span>\n      <span class=\"cg-net\">净资产 {{ net }}</span>\n      <button class=\"cg-close\" @click=\"store.close()\">✕</button>\n    </div>\n    <div v-if=\"acct.news\" class=\"cg-news\">{{ acct.news.sentiment === 'good' ? '📈' : '📉' }} {{ acct.news.text }}</div>\n    <div class=\"cg-tabs\">\n      <button :class=\"{ on: tab === 'market' }\" @click=\"tab = 'market'\">行情</button>\n      <button :class=\"{ on: tab === 'positions' }\" @click=\"tab = 'positions'\">持仓</button>\n      <button :class=\"{ on: tab === 'loan' }\" @click=\"tab = 'loan'\">借贷</button>\n      <button :class=\"{ on: tab === 'assets' }\" @click=\"tab = 'assets'\">资产</button>\n    </div>\n\n    <div v-if=\"tab === 'market' && !detail\" class=\"cg-list\">\n      <div v-for=\"s in STOCKS\" :key=\"s.code\" class=\"cg-row\" @click=\"detail = s.code\">\n        <div class=\"cg-row-name\">{{ s.name }}<span class=\"cg-code\">{{ s.code }}</span></div>\n        <SparkLine :data=\"acct.priceHistory[s.code]\" />\n        <div class=\"cg-price\">{{ acct.prices[s.code] }}</div>\n        <div class=\"cg-pct\" :class=\"pct(s.code) >= 0 ? 'up' : 'down'\">{{ pct(s.code).toFixed(2) }}%</div>\n      </div>\n    </div>\n\n    <div v-else-if=\"tab === 'market' && detail\" class=\"cg-detail\">\n      <button @click=\"detail = null\">← 返回</button>\n      <h3>{{ detail }}</h3>\n      <SparkLine :data=\"acct.priceHistory[detail]\" :width=\"300\" :height=\"120\" />\n      <div>现价 {{ acct.prices[detail] }}</div>\n      <div v-if=\"acct.positions[detail]\">强平价：{{ liquidationPrice(acct.positions[detail]) }}</div>\n      <label>数量 <input v-model.number=\"qty\" type=\"number\" min=\"1\" /></label>\n      <label>杠杆 <input v-model.number=\"leverage\" type=\"range\" min=\"1\" max=\"100\" /> ×{{ leverage }}</label>\n      <div class=\"cg-btns\">\n        <button class=\"buy\" @click=\"buy(detail, 'long')\">做多</button>\n        <button class=\"sell\" @click=\"buy(detail, 'short')\">做空</button>\n      </div>\n    </div>\n\n    <div v-else-if=\"tab === 'positions'\" class=\"cg-list\">\n      <div v-if=\"!Object.keys(acct.positions).length\" class=\"cg-empty\">空仓</div>\n      <div v-for=\"(p, code) in acct.positions\" :key=\"code\" class=\"cg-row\">\n        <div class=\"cg-row-name\">{{ code }} {{ p.side === 'long' ? '多' : '空' }} ×{{ p.leverage }}</div>\n        <div class=\"cg-pct\" :class=\"positionPnl(p, acct.prices[code]) >= 0 ? 'up' : 'down'\">\n          {{ positionPnl(p, acct.prices[code]) }}\n        </div>\n        <button @click=\"close(code)\">平仓</button>\n      </div>\n    </div>\n\n    <div v-else-if=\"tab === 'loan'\" class=\"cg-assets\">\n      <template v-if=\"!acct.loan && acct.debt <= 0\">\n        <div>可借额度：{{ store.loanOffer().maxAmount }}（利率 {{ store.loanOffer().rate * 100 }}%，期限 100 跳）</div>\n        <input v-model.number=\"loanAmt\" type=\"number\" min=\"1\" placeholder=\"借款金额\" />\n        <button @click=\"doBorrow\">借款</button>\n      </template>\n      <template v-if=\"acct.loan\">\n        <div>\n          借款本金：{{ acct.loan.principal }}（{{\n            acct.loan.highInterest ? '高利贷·还 2.5 倍+已累计利息 ' + acct.loan.accrued : '利率 ' + acct.loan.rate * 100 + '%'\n          }}）\n        </div>\n        <div v-if=\"!acct.loan.highInterest\">到期：第 {{ acct.loan.dueTick }} 跳（当前 {{ acct.tick }}）</div>\n        <button @click=\"doRepay\">还清</button>\n      </template>\n      <template v-if=\"acct.debt > 0\">\n        <div class=\"cg-frozen\">催收中债务：{{ acct.debt }}</div>\n        <input v-model.number=\"debtAmt\" type=\"number\" min=\"1\" placeholder=\"还债金额\" />\n        <button @click=\"doPayDebt\">还债</button>\n        <button v-if=\"!acct.loan\" class=\"danger\" @click=\"doBorrowHigh\">借高利贷（500，还 2.5 倍）</button>\n      </template>\n    </div>\n\n    <div v-else class=\"cg-assets\">\n      <div>现金：{{ acct.cash }}</div>\n      <div>净资产：{{ net }}</div>\n      <div>累计亏损：{{ acct.cumulativeLoss }}（破产线 250）</div>\n      <div v-if=\"acct.frozen\" class=\"cg-frozen\">⛔ 账户冻结中</div>\n      <div class=\"cg-exchange\">\n        <h4>UP 兑换（1 UP = 1 币，双向 1% 手续费）</h4>\n        <input v-model.number=\"exchangeAmt\" type=\"number\" min=\"1\" placeholder=\"金额\" />\n        <div class=\"cg-btns\">\n          <button @click=\"doDeposit\">入金（UP→币）</button>\n          <button @click=\"doWithdraw\">出金（币→UP）</button>\n        </div>\n      </div>\n      <div class=\"cg-bankruptcy\">\n        <div>破产次数：{{ acct.bankruptcyCount }}</div>\n        <button class=\"danger\" @click=\"openPreview\">申请破产清算</button>\n        <div v-if=\"previewing\" class=\"cg-modal\">\n          <h4>破产清算清单（确认后不可撤销）</h4>\n          <div v-for=\"(s, i) in preview?.steps ?? []\" :key=\"i\">【{{ s.category }}】{{ s.name }} → 抵 {{ s.proceeds }}</div>\n          <div>抵债合计 {{ preview?.totalProceeds }}，剩余债务 {{ preview?.remainingDebt }}</div>\n          <div class=\"cg-btns\">\n            <button class=\"danger\" @click=\"doBankruptcy\">确认清算</button>\n            <button @click=\"previewing = false\">取消</button>\n          </div>\n        </div>\n      </div>\n      <div class=\"cg-inheritance\">\n        <div>\n          遗产估值 {{ store.inheritancePreview.estate }}｜现在死了要交：税 {{ store.inheritancePreview.tax }} + 过户费\n          {{ store.inheritancePreview.fee }}\n        </div>\n        <button class=\"danger\" @click=\"confirmDeath = true\">宣告死亡 / 放弃本局</button>\n        <div v-if=\"confirmDeath\" class=\"cg-modal\">\n          <p>宣告后账户打上死亡标记，下次打开交易所先扣缴遗产税。确定？</p>\n          <div class=\"cg-btns\">\n            <button class=\"danger\" @click=\"doMarkDeath\">确定</button>\n            <button @click=\"confirmDeath = false\">取消</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.cg-panel {\n  position: fixed;\n  inset: 0;\n  background: #0d0f14;\n  color: #e6e6e6;\n  pointer-events: auto;\n  display: flex;\n  flex-direction: column;\n  font-size: 14px;\n}\n.cg-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  border-bottom: 1px solid #262a33;\n}\n.cg-title {\n  font-weight: 700;\n}\n.cg-net {\n  margin-left: auto;\n  opacity: 0.8;\n}\n.cg-close {\n  background: none;\n  border: none;\n  color: #999;\n  font-size: 16px;\n}\n.cg-news {\n  padding: 6px 14px;\n  background: #1a2030;\n  font-size: 12px;\n}\n.cg-tabs {\n  display: flex;\n  gap: 4px;\n  padding: 8px 14px;\n}\n.cg-tabs button {\n  flex: 1;\n  padding: 6px;\n  background: #171b23;\n  border: 1px solid #262a33;\n  color: #ccc;\n  border-radius: 6px;\n}\n.cg-tabs button.on {\n  background: #24406e;\n  color: #fff;\n}\n.cg-list {\n  flex: 1;\n  overflow-y: auto;\n  padding: 0 14px;\n}\n.cg-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 0;\n  border-bottom: 1px solid #1c2029;\n}\n.cg-row-name {\n  flex: 1;\n}\n.cg-code {\n  opacity: 0.5;\n  margin-left: 6px;\n  font-size: 11px;\n}\n.cg-pct.up {\n  color: #e5484d;\n}\n.cg-pct.down {\n  color: #30a46c;\n}\n.cg-detail,\n.cg-assets {\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.cg-btns {\n  display: flex;\n  gap: 10px;\n}\n.cg-btns .buy {\n  flex: 1;\n  background: #e5484d;\n  color: #fff;\n  border: none;\n  padding: 10px;\n  border-radius: 6px;\n}\n.cg-btns .sell {\n  flex: 1;\n  background: #30a46c;\n  color: #fff;\n  border: none;\n  padding: 10px;\n  border-radius: 6px;\n}\n.cg-empty {\n  opacity: 0.5;\n  text-align: center;\n  padding: 30px;\n}\n.cg-frozen {\n  color: #f7b955;\n}\n.danger {\n  background: #5c1a1a;\n  color: #ffb3b3;\n  border: 1px solid #8a2f2f;\n  padding: 8px;\n  border-radius: 6px;\n}\n.cg-modal {\n  border: 1px solid #8a2f2f;\n  background: #151019;\n  border-radius: 8px;\n  padding: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  font-size: 13px;\n}\n</style>\n"],"sourceRoot":""}]);
